"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["33784"],{66165(e){e.exports=JSON.parse('{"id":"FIN-822","slug":"payday-loan","term":"Payday Loan","also_known_as":[],"difficulty":"Beginner","definition":"A payday loan is a small, short-term, high-cost loan, typically due on the borrower\'s next payday, often used to cover urgent expenses.","explanation":["Payday loans are usually for small amounts and are often easy to obtain, with minimal credit checks. Borrowers typically repay the full amount, plus fees, within a few weeks.","The costs are extremely high. A lender might charge a fee of 15 for every 100 borrowed for two weeks. That may not sound like much, but expressed as an annual percentage rate, it is equivalent to around 390% a year, far higher than credit cards or personal loans.","The main danger is the debt cycle. Borrowers who cannot repay on time may roll the loan over or take out a new one to repay the old one, adding more fees each time. A small loan can quickly grow into a much larger debt.","Because of these risks, many countries and states regulate payday lending heavily. Some cap interest rates and fees, limit how many times a loan can be rolled over or ban payday loans entirely. Alternatives may include credit union loans, employer salary advances, hardship funds or agreeing a payment plan directly with the creditor."],"note":"","total":1500,"prev":{"slug":"payback-period","term":"Payback Period"},"next":{"slug":"payment-gateway","term":"Payment Gateway"}}')}}]);